import json

lower=(2,2,2,0,0); upper=(4,4,4,4,4); hs=(1,2,3,4)
def wt(p): return sum(p)
def parts(d,lo=lower,hi=upper):
 out=[]
 def rec(i,prev,a,left):
  if i==5:
   if left==0 and all(a[k]>=lo[k] and a[k]<=hi[k] for k in range(5)): out.append(tuple(a))
   return
  for x in range(min(prev,hi[i],left),lo[i]-1,-1): rec(i+1,x,a+[x],left-x)
 rec(0,hi[0],[],d)
 return out
def hstrip(lam,mu):
 # mu/lam horizontal iff each column gains at most one box
 for c in range(1,5):
  if sum(x>=c for x in mu)-sum(x>=c for x in lam)>1:return False
 return True
def eye(n): return [[int(i==j) for j in range(n)] for i in range(n)]
def swaprows(A,i,j): A[i],A[j]=A[j],A[i]
def swapcols(A,i,j):
 for r in A:r[i],r[j]=r[j],r[i]
def rowadd(A,i,j,q):
 for c in range(len(A[0])): A[i][c]+=q*A[j][c]
def coladd(A,i,j,q):
 for r in range(len(A)): A[r][i]+=q*A[r][j]
def smith_witness(M):
 m=len(M); n=(len(M[0]) if m else NC)
 A=[r[:] for r in M]; U=eye(m); V=eye(n); k=0
 while k<m and k<n:
  pos=None
  for i in range(k,m):
   for j in range(k,n):
    if A[i][j] and (pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]])):pos=(i,j)
  if pos is None: break
  swaprows(A,k,pos[0]); swaprows(U,k,pos[0]); swapcols(A,k,pos[1]); swapcols(V,k,pos[1])
  while True:
   changed=False
   for i in range(k+1,m):
    if A[i][k]:
     q=A[i][k]//A[k][k]; rowadd(A,i,k,-q); rowadd(U,i,k,-q)
     if A[i][k]: swaprows(A,i,k); swaprows(U,i,k); changed=True; break
   if changed: continue
   for j in range(k+1,n):
    if A[k][j]:
     q=A[k][j]//A[k][k]; coladd(A,j,k,-q); coladd(V,j,k,-q)
     if A[k][j]: swapcols(A,j,k); swapcols(V,j,k); changed=True; break
   if changed: continue
   bad=None
   for i in range(k+1,m):
    for j in range(k+1,n):
     if A[i][j]%A[k][k]: bad=(i,j); break
    if bad: break
   if bad:
    # introduce A[bad] into pivot column, then Euclidean-reduce
    coladd(A,k,bad[1],1); coladd(V,k,bad[1],1); changed=True; continue
   break
  if A[k][k]<0:
   rowadd(A,k,k,-2); rowadd(U,k,k,-2)
  k+=1
 return U,V,A,k
def matmul(A,B):
 if not A:return []
 return [[sum(A[i][z]*B[z][j] for z in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def det(A):
 n=len(A)
 if n==0:return 1
 B=[r[:] for r in A]; s=1; prev=1
 for k in range(n-1):
  if B[k][k]==0:
   z=next((i for i in range(k+1,n) if B[i][k]),None)
   if z is None:return 0
   swaprows(B,k,z);s=-s
  p=B[k][k]
  for i in range(k+1,n):
   for j in range(k+1,n):B[i][j]=(B[i][j]*p-B[i][k]*B[k][j])//prev
  prev=p
 return s*B[-1][-1]
W=[]
for d in range(6,21):
 C=parts(d); NC=len(C)
 rows=[]; labels=[]
 for h in hs:
  for lam in parts(d-h):
   row=[int(hstrip(lam,mu)) for mu in C]
   if any(row): rows.append(row);labels.append([h,list(lam)])
 M=rows; U,V,D,r=smith_witness(M)
 assert D==matmul(matmul(U,M),V) if M else (D==[] and U==[] and V==[[1]])
 assert det(U) in (1,-1) and det(V) in (1,-1)
 W.append({'degree':d,'columns':[list(x) for x in C],'rowLabels':labels,'M':M,'U':U,'V':V,'D':D,'rank':r,'detU':det(U),'detV':det(V)})
assert W[0]['M']==[] and W[0]['U']==[] and W[0]['V']==[[1]] and W[0]['D']==[]
print(json.dumps({'lower':list(lower),'upper':list(upper),'hDegrees':list(hs),'witnesses':W},separators=(',',':')))
